public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create a new bipartite graph with the specified number of vertices
    Graph<V,E> bipartiteGraph = new Graph<V,E>(target.getNumVertices(), target.getNumVertices());

    // Add edges between the vertices in the bipartite graph
    for (V vertex : target.getVertices()) {
        for (V neighbor : target.getNeighbors(vertex)) {
            bipartiteGraph.addEdge(vertex, neighbor);
        }
    }

    // Add the vertices and edges to the result map
    for (V vertex : bipartiteGraph.getVertices()) {
        resultMap.put(vertex.getId(), vertex);
