/**
 * Computes the minimal separators of the given edge $e$ in the neighborhood of $e$.
 * @param edge the edge to compute the minimal separators for
 * @param neighborEdge the neighbor edge of $e$
 * @return the list of minimal separators of $e$ in the neighborhood of $e$
 */
private List<Pair<Integer, Integer>> computeMinimalSeparators(E edge, E neighborEdge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (int i = 0; i < edge.getLength(); i++) {
        for (int j = 0; j < neighborEdge.getLength(); j++) {
            if (edge.get(i) != neighborEdge.get(j)) {
                separators.add(new Pair<>(i, j));
            }
        }
    }
    return separators;
}

